import { useState, useEffect, useCallback, type FormEvent } from 'react';
import { useNavigate, Navigate } from 'react-router-dom';
import { Lock, Shield, Loader2 } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { useI18n } from '@/i18n/I18nContext';
import { logger, resolveAppUrl } from '@lark-apaas/client-toolkit-lite';
import { toast } from 'sonner';
import { decryptPassword } from '@/lib/password-crypto';

const AUTH_KEY = '__app_ledlight_admin_auth';
export const PASSWORD_KEY = '__app_ledlight_admin_password';
const DEFAULT_PASSWORD = 'admin123';

/**
 * 从远程 data/settings.json 拉取管理员密码
 * 部署包不包含 data/ 目录，但用户 GitHub 仓库里有，拉取后会覆盖默认值
 * 失败时静默回退到 localStorage / 默认密码
 */
async function fetchRemoteAdminPassword(): Promise<string | null> {
  try {
    const url = resolveAppUrl('/data/settings.json') + (resolveAppUrl('/data/settings.json').includes('?') ? '&' : '?') + `_t=${Date.now()}`;
    const res = await fetch(url, { cache: 'no-store' });
    if (!res.ok) return null;
    const data = await res.json();
    // 密码在 settings.json 中是加密存储的，需要解密
    if (data && typeof data.adminPassword === 'string' && data.adminPassword.length >= 6) {
      const decrypted = decryptPassword(data.adminPassword);
      if (decrypted && decrypted.length >= 6) {
        return decrypted;
      }
      // 兼容明文密码（旧版本可能是明文，后续可移除）
      return data.adminPassword;
    }
    return null;
  } catch (err) {
    logger.warn('[AdminLogin] Failed to fetch remote settings:', String(err));
    return null;
  }
}

/**
 * 同步读本地密码（localStorage → 默认）
 */
export function getLocalAdminPassword(): string {
  try {
    const saved = localStorage.getItem(PASSWORD_KEY);
    if (saved && typeof saved === 'string' && saved.length >= 6) {
      return saved;
    }
  } catch {
    // ignore
  }
  return DEFAULT_PASSWORD;
}

/**
 * 异步获取管理员密码
 * 优先级：本地自定义 > 远程 > 默认
 * 🔴 重要：如果本地已经有非默认密码（用户改过），不被远程覆盖，保证密码永久固定
 * - 刷新页面不丢失
 * - 上传新部署包不还原
 * - 远程 data/settings.json 的密码只在本地是默认值时才同步过来
 */
export async function getAdminPassword(): Promise<string> {
  const localPwd = getLocalAdminPassword();
  
  // 如果本地密码已经不是默认值（用户改过），直接使用本地密码，不被远程覆盖
  // 这保证了：刷新页面 / 上传新部署包 / 换浏览器（只要 localStorage 在）密码都不会恢复
  if (localPwd !== DEFAULT_PASSWORD) {
    logger.info(`[AdminLogin] Local password is customized, skipping remote fetch`);
    return localPwd;
  }

  // 本地是默认值时，尝试从远程拉取（可能管理员改过并同步到 GitHub）
  const remote = await fetchRemoteAdminPassword();
  if (remote && remote.length >= 6) {
    try {
      localStorage.setItem(PASSWORD_KEY, remote);
      logger.info(`[AdminLogin] Fetched remote password, saved to localStorage`);
    } catch {
      // ignore
    }
    return remote;
  }
  return localPwd;
}

export default function AdminLoginPage() {
  const { adminT, adminLanguage, setAdminLanguage } = useI18n();
  const navigate = useNavigate();
  const [password, setPassword] = useState('');
  const [error, setError] = useState('');
  const [isAuthenticated, setIsAuthenticated] = useState<boolean | null>(null);
  const [isLoading, setIsLoading] = useState(true);

  // 页面加载时先尝试从远程 data/settings.json 拉取最新密码
  // 这样即使上传了新部署包，只要 GitHub 上有 data/settings.json，密码就不会还原
  // 换浏览器也能同步到同一个密码
  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        await getAdminPassword();
      } catch {
        // 远程拉取失败不影响登录，继续用本地/默认密码
      } finally {
        if (!cancelled) setIsLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, []);

  // Check if already logged in
  useEffect(() => {
    try {
      const auth = localStorage.getItem(AUTH_KEY);
      if (auth === 'true') {
        navigate('/admin/dashboard', { replace: true });
      }
    } catch {
      // ignore
    }
  }, [navigate]);

  const handleSubmit = async (e: FormEvent) => {
    e.preventDefault();
    setError('');

    const currentPassword = await getAdminPassword();
    if (password === currentPassword) {
      try {
        localStorage.setItem(AUTH_KEY, 'true');
      } catch {
        // ignore
      }
      toast.success(adminT('admin.loginSuccessful'));
      navigate('/admin/dashboard', { replace: true });
    } else {
      setError(adminT('admin.loginError'));
    }
  };

  if (isAuthenticated === true) {
    return <Navigate to="/admin/dashboard" replace />;
  }

  return (
    <div className="admin-theme min-h-screen bg-background flex items-center justify-center px-4">
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <div className="inline-flex items-center justify-center w-16 h-16 rounded-2xl bg-primary/10 mb-4">
            <Shield className="size-8 text-primary" />
          </div>
          <h1 className="text-2xl font-bold text-foreground mb-2">{adminT('admin.adminPanel')}</h1>
           <p className="text-sm text-muted-foreground">{adminT('admin.adminTitle')}</p>
        </div>

        <Card className="border-border/40 bg-card shadow-xl">
          <CardHeader className="pb-4">
            <CardTitle className="text-lg">{adminT('admin.login')}</CardTitle>
            <CardDescription>{adminT('admin.enterPassword')}</CardDescription>
          </CardHeader>
          <CardContent>
            <form onSubmit={handleSubmit} className="space-y-4">
              <div>
                <label className="text-xs font-medium text-foreground mb-1.5 block">
                  {adminT('admin.password')}
                </label>
                <div className="relative">
                  <Lock className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
                  <Input
                    type="password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    placeholder="••••••••"
                    className="pl-9 bg-background/60"
                    autoFocus
                  />
                </div>
                {error && <p className="text-xs text-destructive mt-1.5">{error}</p>}
              </div>

              <Button
                type="submit"
                className="w-full bg-primary hover:bg-primary/90 text-primary-foreground"
                disabled={isLoading}
              >
                {isLoading ? (
                  <>
                    <Loader2 className="size-4 mr-2 animate-spin" />
                    Loading...
                  </>
                ) : (
                  adminT('admin.loginBtn')
                )}
              </Button>

              <p className="text-[10px] text-center text-muted-foreground">
                默认密码：<span className="font-mono text-foreground/70">admin123</span>
              </p>
            </form>
          </CardContent>
        </Card>

        <div className="text-center mt-6">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => navigate('/')}
            className="text-xs text-muted-foreground"
          >
             ← 返回网站
          </Button>
        </div>
      </div>
    </div>
  );
}
